#!/usr/bin/env node
// Generates dist/plugin.mjs — the ESM entry that opencode's plugin loader
// imports (it uses `await import()` + reads `mod.default`, so the CJS
// `exports.default` from tsc would otherwise be missed).
const fs = require('fs');
const path = require('path');

const out = path.join(__dirname, '..', 'dist', 'plugin.mjs');
const content = [
  "// Generated by scripts/make-plugin-mjs.js — re-exports the CJS plugin object",
  "// as a real ESM default export so opencode's ESM plugin loader picks it up.",
  "import cjs from './plugin.js';",
  "// Node interop: `import cjs from './plugin.js'` yields { default: plugin }.",
  "// Bun (the runtime opencode is built with) unwraps the CJS default, so",
  "// cjs.default is already the plugin object and cjs.default is undefined.",
  "export default (cjs && cjs.default) ? cjs.default : cjs;",
  '',
].join('\n');

fs.writeFileSync(out, content);
console.log('wrote ' + out);

// dist/v2.mjs is authored as ESM (src/v2.mjs) because @opencode/plugin is
// ESM-only and cannot be imported from the CommonJS build; tsc does not emit it.
const v2src = path.join(__dirname, '..', 'src', 'v2.mjs');
const v2out = path.join(__dirname, '..', 'dist', 'v2.mjs');
fs.copyFileSync(v2src, v2out);
console.log('wrote ' + v2out);
